  "bi-deque": {
    cpp: "#include <algorithm>\n#include <deque>\n#include <iostream>\n#include <string>\n#include <vector>\nusing namespace std;\n\nvoid show(const string& label, const deque<string>& d) {\n    cout << label << \":\";\n    for (const auto& x : d) cout << \" \" << x;\n    cout << \" (\" << d.size() << \")\" << endl;\n}\n\nint main() {\n    // A support line: customers join at the back, a VIP goes to the front\n    deque<string> line = {\"Asha\", \"Ben\"};\n    line.push_back(\"Chen\");\n    line.push_front(\"Dana\");\n    show(\"line\", line);\n    cout << \"next: \" << line.front() << \", last: \" << line.back() << \", second: \" << line[1] << endl;\n    line.pop_front();                          // Dana is served\n    line.pop_back();                           // Chen gives up and leaves\n    line.insert(line.begin() + 1, \"Eli\");      // a middle insert costs O(n)\n    show(\"after serving\", line);\n    rotate(line.begin(), line.begin() + 1, line.end());   // round robin: the front goes to the back\n    show(\"rotated\", line);\n\n    // Recently viewed: keep only the last 3 products\n    deque<string> recent;\n    for (string p : {\"phone\", \"case\", \"charger\", \"earbuds\"}) {\n        recent.push_back(p);\n        if (recent.size() > 3) recent.pop_front();\n    }\n    show(\"recently viewed\", recent);\n\n    // Hottest temperature in every 3-day window: a deque of indexes, values decreasing\n    vector<int> temp = {31, 29, 33, 30, 28, 35, 34};\n    deque<int> idx;\n    cout << \"3-day max:\";\n    for (int i = 0; i < (int)temp.size(); i++) {\n        while (!idx.empty() && temp[idx.back()] <= temp[i]) idx.pop_back();\n        idx.push_back(i);\n        if (idx.front() <= i - 3) idx.pop_front();   // left the window\n        if (i >= 2) cout << \" \" << temp[idx.front()];\n    }\n    cout << endl;\n    line.clear();\n    cout << \"empty after clear: \" << (line.empty() ? \"yes\" : \"no\") << endl;\n}",
    python: "from collections import deque\n\n\ndef show(label, d):\n    print(f\"{label}: {' '.join(d)} ({len(d)})\")\n\n\n# A support line: customers join at the back, a VIP goes to the front\nline = deque([\"Asha\", \"Ben\"])\nline.append(\"Chen\")\nline.appendleft(\"Dana\")\nshow(\"line\", line)\nprint(f\"next: {line[0]}, last: {line[-1]}, second: {line[1]}\")\nline.popleft()                 # Dana is served\nline.pop()                     # Chen gives up and leaves\nline.insert(1, \"Eli\")          # a middle insert costs O(n)\nshow(\"after serving\", line)\nline.rotate(-1)                # round robin: the front goes to the back\nshow(\"rotated\", line)\n\n# Recently viewed: maxlen drops the oldest item by itself\nrecent = deque(maxlen=3)\nfor p in [\"phone\", \"case\", \"charger\", \"earbuds\"]:\n    recent.append(p)\nshow(\"recently viewed\", recent)\n\n# Hottest temperature in every 3-day window: a deque of indexes, values decreasing\ntemp = [31, 29, 33, 30, 28, 35, 34]\nidx = deque()\nbest = []\nfor i, t in enumerate(temp):\n    while idx and temp[idx[-1]] <= t:\n        idx.pop()\n    idx.append(i)\n    if idx[0] <= i - 3:        # left the window\n        idx.popleft()\n    if i >= 2:\n        best.append(str(temp[idx[0]]))\nprint(\"3-day max:\", \" \".join(best))\nline.clear()\nprint(\"empty after clear:\", \"yes\" if not line else \"no\")",
  },
